        parent::__construct($spec);
    } catch (Throwable $exception) {
        try {
            parent::__construct('PT0S');

            if ($isStringSpec) {
                if (!preg_match('/^P
                    (?:(?<year>[+-]?\d*(?:\.\d+)?)Y)?
                    (?:(?<month>[+-]?\d*(?:\.\d+)?)M)?
                    (?:(?<week>[+-]?\d*(?:\.\d+)?)W)?
                    (?:(?<day>[+-]?\d*(?:\.\d+)?)D)?
                    (?:T
                        (?:(?<hour>[+-]?\d*(?:\.\d+)?)H)?
                        (?:(?<minute>[+-]?\d*(?:\.\d+)?)M)?
                        (?:(?<second>[+-]?\d*(?:\.\d+)?)S)?
                    )?
